css:
/* Dense analytical theme: grid surfaces, clear status, keyboard and mobile. */
:root { --bg: #eaf0fa; --surface: #ffffff; --border: #a9b9d2; --text: #15233c; --text-medium: #263e62; --text-muted: #445b79; --text-ghost: #50647e; --accent-strong: #6532a5; --radius: 6px; }
:root.dark { --bg: #10182a; --surface: #19253c; --border: #516585; --text: #eef4ff; --text-medium: #d2dff4; --text-muted: #b0c4e2; --text-ghost: #a5b8d5; --accent-strong: #d2b4ff; }
.header { background: var(--surface); box-shadow: 0 2px 0 var(--accent-strong); gap: 8px; }
#brandBtn { font-family: ui-monospace, Consolas, monospace; font-size: clamp(1.4rem, 3vw, 2.5rem); letter-spacing: -.06em; }
.card-tile { border: 1px solid var(--border); border-left: 4px solid var(--accent-strong); border-radius: 6px; background-image: linear-gradient(120deg, transparent 75%, var(--bg)); }
.card-tile:hover, .card-tile:focus-within { box-shadow: 0 0 0 2px var(--accent-strong); }
.card-tags { gap: 6px; }
.card-tag { font-family: ui-monospace, Consolas, monospace; color: var(--accent-strong); background: var(--bg); border: 1px solid var(--border); border-radius: 4px; }
.card-content code, .card-content pre { background: var(--bg); color: var(--text); border: 1px solid var(--border); padding: 4px; overflow-wrap: anywhere; }
.search-input-wrapper { border: 1px solid var(--border); box-shadow: inset 3px 0 var(--accent-strong); }
.menu-panel { background: var(--surface); border-left: 2px solid var(--accent-strong); }
:root:not(.high-contrast) :focus-visible { outline: 3px dashed var(--accent-strong); outline-offset: 4px; }
@media (max-width: 540px) { .card-tile { border-left-width: 3px; } .header { gap: 4px; } }
@media (prefers-reduced-motion: reduce) { .card-tile { transition: none; animation: none; } }
@media (forced-colors: active) { .card-tile { background-image: none; border-color: CanvasText; } }
@media print { :root, :root.dark { --bg: white; --surface: white; --text: black; --border: #777; --accent-strong: black; } .card-tile { background: white; break-inside: avoid; box-shadow: none; } .header, .menu-panel { display: none; } }

/* Shared finishing rules keep links, placeholders and selected controls on
   the same tested palette. Existing high-contrast rules retain control. */
:root:not(.high-contrast) a { color: var(--accent-strong); text-underline-offset: .16em; }
:root:not(.high-contrast) a:hover { color: var(--text); }
:root:not(.high-contrast) .breadcrumb.current { color: var(--text-muted); }
:root:not(.high-contrast) input::placeholder, :root:not(.high-contrast) textarea::placeholder { color: var(--text-muted); opacity: 1; }
:root:not(.high-contrast) .density-btn.active { background: var(--text); color: var(--bg); border-color: var(--text); }
:root:not(.high-contrast) .density-btn:hover { outline: 1px solid var(--text); }
:root:not(.high-contrast) .save-status.saved { color: var(--accent-strong); background: var(--surface); border-color: var(--accent-strong); }
@media (prefers-reduced-motion: reduce) { .save-status, .density-btn { transition: none; animation: none; } }
